'use strict';
const L=window.DutyLogic, DB=window.LAW_DATABASE, articles=DB.articles;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Number(n).toLocaleString('ru-RU');
const stamp=t=>new Date(t).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
const date=t=>new Date(t).toLocaleDateString('ru-RU',{day:'2-digit',month:'short',year:'numeric'});
const icons={shield:'M12 3 3 6v6c0 5 9 9 9 9s9-4 9-9V6z M9 12l2 2 4-4',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M4 4h6c2 0 2 2 2 2s0-2 2-2h6v15h-6c-2 0-2 2-2 2s0-2-2-2H4z M12 6v15',case:'M9 6V3h6v3 M3 6h18v15H3z M3 11h18 M10 11v3h4v-3',check:'M9 5H5v16h14V5h-4 M9 3h6v4H9z M8 13l3 3 5-5',scale:'M12 3v18 M5 21h14 M4 7h16 M6 7l-4 7h8z M18 7l-4 7h8z',file:'M14 3H5v18h14V8z M14 3v5h5 M8 12h8 M8 16h6',archive:'M3 3h18v4H3z M5 7v14h14V7 M9 12h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',plus:'M12 5v14 M5 12h14',arrow:'M4 12h16 M14 6l6 6-6 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',copy:'M8 8h13v13H8z M16 8V3H3v13h5',star:'m12 3 3 6 6 1-4 5 1 6-6-3-6 3 1-6-4-5 6-1z',pin:'M9 3h6v5l3 3v3H6v-3l3-3z M12 14v7',close:'M5 5l14 14 M19 5 5 19',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',play:'m8 4 12 8-12 8z',pause:'M8 4v16 M16 4v16',link:'M10 14l4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',alert:'m12 3 10 18H2z M12 9v5 M12 17v1',person:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3c0-6 16-6 16 0v3',radio:'M5 8h14v13H5z M7 8 17 2 M8 13h3 M8 17h3 M16 13v4'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.shield}"/></svg>`;
const navs=[['home','grid','Обзор'],['laws','book','Законодателька'],['case','case','Задержание'],['procedure','check','Процедуры'],['counsel','scale','Адвокат'],['report','file','Рапорт'],['archive','archive','Архив дел']];
const titles={materials:['Материалы дела','Сохранённые записи и документы.'],home:['Оперативный обзор','Всё для уверенной смены — в одном месте.'],laws:['Законодателька Boston','Полные тексты четырёх кодексов, всегда под рукой.'],case:['Законка задержания','Основания, порядок действий и права — статьи ПК Boston.'],procedure:['Порядок действий','Отмечай выполненные шаги и фиксируй время.'],counsel:['Разбор с адвокатом','Обстоятельства → норма → доказательства → процедура.'],report:['Подготовка рапорта','Черновик на основе твоих записей. Проверь перед отправкой.'],archive:['Архив дел','Сохранённые материалы и история задержаний.'],settings:['Настройки','Твой профиль, внешний вид и резервные копии.']};
let state={version:1,profile:{name:'',badge:'',callsign:'',rank:'Deputy Sheriff'},cases:[],activeId:null,favorites:[],settings:{sound:true,compact:false,top:false}};
let storageBroken=false;
try {const raw=localStorage.getItem('boston-duty-v1');if(raw){const data=JSON.parse(raw);L.validateBackup(data);state={...state,...data,profile:{...state.profile,...data.profile},settings:{...state.settings,...data.settings}};}}catch(e){storageBroken=true;}
let view='home',query='',code='Все',favoritesOnly=false,sanctionOnly=false,showRetired=false,limit=30,counselTopic='basis',objection='';
let toastTimeout;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function save(){if(storageBroken)return;try{localStorage.setItem('boston-duty-v1',JSON.stringify(state));$('#save-state')?.classList.remove('bad');}catch(e){$('#save-state')?.classList.add('bad');toast('Не удалось сохранить. Экспортируй резервную копию в настройках.');}}
const current=()=>state.cases.find(c=>c.id===state.activeId);
const law=(code,ref)=>articles.find(a=>a.code===code&&a.ref===ref);
const lawButton=(code,ref)=>`<button class="text-link" data-action="law-ref" data-code="${code}" data-ref="${ref}">${code} ${ref} ${icon('arrow')}</button>`;
function log(text,c=current()){if(c){c.timeline.push({at:Date.now(),text});save();}}
function field(label,key,value,placeholder='',wide=false,type='text'){return `<label class="field ${wide?'wide':''}"><span>${label}</span><input id="field-${key}" data-field="${key}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off"></label>`;}
function textarea(label,key,value,placeholder='',rows=4){return `<label class="field wide"><span>${label}</span><textarea id="field-${key}" data-field="${key}" rows="${rows}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></label>`;}
function button(text,action,kind='secondary',ic=''){return `<button class="btn ${kind}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;}
function seal(size=''){return `<div class="seal ${size}" aria-hidden="true"><div class="seal-ring">LOS SANTOS COUNTY<span>SHERIFF'S DEPARTMENT</span></div><svg viewBox="0 0 120 120"><path d="m60 13 12 25 28-6-10 27 22 18-29 4-8 28-15-24-25 15 3-29-28-11 27-12-4-29 23 16z" fill="currentColor"/><circle cx="60" cy="61" r="22" fill="#151c17"/><path d="m60 42 15 6v13c0 12-15 19-15 19s-15-7-15-19V48z" fill="none" stroke="currentColor" stroke-width="2"/><path d="m52 60 6 6 11-12" fill="none" stroke="currentColor" stroke-width="3"/></svg></div>`;}
function render(){
  const focus=document.activeElement?.id;const pos=document.activeElement?.selectionStart;const end=document.activeElement?.selectionEnd;
  const c=current(),activeCount=state.cases.filter(c=>c.status==='active').length;
  document.body.classList.toggle('compact',state.settings.compact);
  $('#app').innerHTML=`<aside class="sidebar"><div class="brand">${seal('mini')}<div><b>ДЕЖУРНЫЙ<span>LSCSD / BOSTON</span></b></div></div><div class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav>${navs.map(([id,ic,text])=>`<button class="nav-item ${view===id?'active':''}" data-nav="${id}" aria-label="${text}" title="${text}">${icon(ic)}<span>${text}</span>${id==='archive'&&activeCount?`<small>${activeCount}</small>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="offline"><i></i><span>Локальная база<span>${articles.length} записей · Boston</span></span>${icon('shield')}</div><button class="nav-item ${view==='settings'?'active':''}" data-nav="settings" aria-label="Настройки" title="Настройки">${icon('settings')}<span>Настройки</span></button><div class="profile"><div class="avatar">${esc((state.profile.name||'DS').split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div><strong>${esc(state.profile.name||'Твой профиль')}</strong><span>${esc(state.profile.callsign||'Укажи позывной в настройках')}</span></div><span class="profile-dot"></span></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb">${icon('shield')}<span>LSCSD</span><span class="slash">/</span><span>${titles[view][0]}</span></div><div class="top-actions"><span id="save-state" class="save-state ${storageBroken?'bad':''}"><i></i>${storageBroken?'Ошибка чтения данных':'Сохранение на устройстве'}</span><button class="icon-btn ${state.settings.top?'on':''}" title="Поверх окон" aria-label="Поверх окон" data-action="top">${icon('pin')}</button><span class="top-clock" id="wall-clock">${stamp(Date.now())}</span></div></header><main><div class="page-heading"><div><div class="eyebrow">BOSTON · SHERIFF'S DESK</div><h1>${titles[view][0]}</h1><p>${titles[view][1]}</p></div>${button('Законка задержания','go-case','primary','book')}</div>${storageBroken?'<div class="notice danger">Сохранённые данные не удалось прочитать. Они не перезаписываются. Экспортируй повреждённый файл в настройках для восстановления.</div>':''}<div id="page">${({home:home,laws:lawsPage,case:casePage,calculator:()=>calculatorPage(),situations:()=>situationsPage(),materials:legacyCasePage,procedure:procedurePage,counsel:counselPage,report:reportPage,archive:archivePage,settings:settingsPage}[view])()}</div><footer><span>Дежурный <b>01</b> · Личный помощник LSCSD</span><span>База от ${date(DB.importedAt)} · <a href="${DB.source}" target="_blank" rel="noopener">Majestic Rules ${icon('link')}</a></span></footer></main></div>`;
  if(focus){const el=document.getElementById(focus);if(el){el.focus();try{el.setSelectionRange(pos,end)}catch{}}}
  tick();
}
function emptyCase(){return `<div class="empty big">${icon('case')}<h2>Начни с карточки задержания</h2><p>Статьи, доказательства, таймер и рапорт будут связаны с одним делом.<br>Каждое новое задержание сохраняется отдельно.</p>${button('Создать карточку','new','primary','plus')}</div>`;}
function home(){const c=current(),closed=state.cases.filter(c=>c.status==='closed').length;
  return `<section class="hero"><div><div class="hero-label"><span class="live-dot"></span>ТВОЙ НАПАРНИК НА СМЕНЕ</div><h2>Порядок в деле.<br><span>Уверенность на смене.</span></h2><p>Законка, процедуры и аргументы —<br>чтобы нужное всегда было под рукой.</p><div class="hero-buttons">${button('Законка задержания','go-case','primary','arrow')}<button class="btn subtle" data-nav="procedure">Порядок действий ${icon('book')}</button></div></div><div class="hero-emblem">${seal()}<div class="emblem-caption">SERVE WITH INTEGRITY <span>LOS SANTOS COUNTY</span></div></div><span class="hero-coordinate">34° 02′ N &nbsp; 118° 14′ W</span></section><div class="stats"><div class="stat"><span>ЗАКОНОДАТЕЛЬНАЯ БАЗА</span><div><b>774</b>${icon('book')}</div><small>УК · АК · ДК · ПК</small></div><div class="stat"><span>ТЕКУЩИЕ ДЕЛА</span><div><b>${state.cases.filter(c=>c.status==='active').length.toString().padStart(2,'0')}</b>${icon('case')}</div><small>${c?esc(c.name||'Личность не заполнена'):'Готов к новой смене'}</small></div><div class="stat"><span>ЗАВЕРШЕНО ДЕЛ</span><div><b>${String(closed).padStart(2,'0')}</b>${icon('archive')}</div><small>Все материалы в архиве</small></div><div class="stat"><span>ИЗБРАННЫЕ СТАТЬИ</span><div><b>${String(state.favorites.length).padStart(2,'0')}</b>${icon('star')}</div><small>Быстрый доступ к важному</small></div></div><div class="home-grid"><section class="panel"><div class="panel-head"><h2>${icon('search')} Быстрый поиск</h2><span class="muted">ПО ВСЕМ КОДЕКСАМ</span></div><div class="searchbox">${icon('search')}<input id="home-search" placeholder="Статья или ситуация: угон, обыск, 17.6…" aria-label="Быстрый поиск"><kbd>↵</kbd></div><div class="quick-chips">${['Неповиновение','Адвокат','Обыск','Миранда','Скорость'].map(t=>`<button data-search="${t}">${t}</button>`).join('')}</div><div class="section-label">ЧАСТО НУЖНО НА СМЕНЕ</div>${[['ПК','17 ч.1','Порядок задержания'],['ПК','22 ч.1','Права задержанного'],['УК','17.6 ч.1','Неповиновение требованию']].map(([co,r,t])=>`<button class="quick-law" data-action="law-ref" data-code="${co}" data-ref="${r}"><span class="law-code ${co==='УК'?'uk':''}">${co}</span><div><strong>${t}</strong><span>Статья ${r}</span></div>${icon('arrow')}</button>`).join('')}</section><section class="panel active-panel"><div class="panel-head"><h2>${icon('book')} Законка задержания</h2><span class="badge green">ПК Boston</span></div><div class="empty small">${icon('shield')}<h3>Нужные нормы под рукой</h3><p>Основания, порядок, права, адвокат,<br>обыск и освобождение.</p>${button('Открыть законку','go-case','secondary','arrow')}</div></section><section class="panel full"><div class="panel-head"><h2>Рабочие инструменты</h2><span class="muted">НА ОДИН ШАГ ВПЕРЁД</span></div><div class="tools-grid">${[['procedure','check','Не пропустить важное','Порядок задержания и журнал шагов'],['counsel','scale','Подготовиться к адвокату','Нормы, доказательства и возражения'],['report','file','Собрать рапорт','Черновик из материалов твоего дела']].map(([v,ic,t,d])=>`<button class="tool-card" data-nav="${v}">${icon(ic)}<strong>${t}</strong><span>${d}</span>${icon('arrow')}</button>`).join('')}</div></section></div>`;
}
function lawsPage(){const result=L.search(articles,query,{code,favorites:favoritesOnly?state.favorites:null,sanction:sanctionOnly,retired:showRetired});
  return `<div class="panel law-search-panel"><div class="searchbox large">${icon('search')}<input id="law-search" aria-label="Поиск по законодательке" value="${esc(query)}" placeholder="Номер статьи, название или описание ситуации…"><kbd>Ctrl K</kbd></div><div class="filter-row"><div class="segmented">${['Все','УК','АК','ДК','ПК'].map(co=>`<button data-code-filter="${co}" class="${code===co?'selected':''}">${co}<small>${co==='Все'?774:articles.filter(a=>a.code===co).length}</small></button>`).join('')}</div><button data-action="favorites-filter" class="filter-btn ${favoritesOnly?'selected':''}">${icon('star')} Избранное</button></div><div class="law-options"><label><input type="checkbox" id="sanction-filter" ${sanctionOnly?'checked':''}> С наказанием</label><label><input type="checkbox" id="retired-filter" ${showRetired?'checked':''}> Показывать отменённые</label><span>${result.length} записей</span></div></div><div class="law-results">${result.slice(0,limit).map(a=>lawCard(a)).join('')||`<div class="empty big">${icon('search')}<h2>Ничего не найдено</h2><p>Попробуй другое слово или отключи фильтры.</p>${button('Сбросить поиск','clear-search','secondary')}</div>`}</div>${result.length>limit?`<div class="load-more">${button('Показать ещё · '+(result.length-limit),'more','secondary')}</div>`:''}<div class="notice">Поиск предлагает связанные нормы. Для квалификации проверь все признаки состава и обстоятельства дела.</div>`;
}
function lawCard(a){const fav=state.favorites.includes(a.id),added=current()?.charges.some(c=>c.id===a.id),retired=L.retired(a);
  return `<article class="law-card ${retired?'retired':''}"><div class="law-card-top"><span class="law-code ${a.code==='УК'?'uk':''}">${a.code}</span><span class="article-number">${esc(a.ref)}</span>${retired?'<span class="badge">Отменена</span>':''}<button class="icon-btn favorite ${fav?'on':''}" aria-label="${fav?'Убрать из избранного':'В избранное'} ${esc(a.ref)}" data-action="favorite" data-id="${a.id}">${icon('star')}</button></div><button class="law-title" data-action="law" data-id="${a.id}">${esc(a.title)}</button><p class="law-excerpt">${esc(a.text)}</p><div class="law-card-foot"><span class="sanction">${a.sanction?icon('scale')+esc(a.sanction):'<span class="muted">Норма без отдельной санкции</span>'}</span><button class="btn small ${added?'added':'secondary'}" data-action="add-law" data-id="${a.id}" ${retired?'disabled':''}>${icon(added?'check':'plus')}${added?'В деле':'В дело'}</button></div></article>`;
}
function timerPanel(c){const activePause=c.timer.pauses.findLast(p=>!p.end);return `<section class="panel timer-panel"><div class="panel-head"><h2>${icon('clock')} Процессуальное время</h2><span class="badge ${activePause?'gold':c.timer.startedAt?'green':''}" id="timer-status">${!c.timer.startedAt?'Не запущено':c.timer.stoppedAt?'Завершено':activePause?'Пауза':'Идёт отсчёт'}</span></div><div class="timer-digits" data-process-clock>${L.formatTime(L.elapsed(c.timer))}</div><div class="timer-caption">из 01:00:00 · ${lawButton('ПК','20 ч.1')}</div>${c.timer.startedAt?`<div class="timer-start">Фактическое задержание: ${stamp(c.timer.startedAt)}</div><div class="timer-buttons">${!c.timer.stoppedAt?button(activePause?'Продолжить отсчёт':'Приостановить',activePause?'resume':'pause','secondary',activePause?'play':'pause'):''}${button('Уточнить начало','timer-edit','ghost','clock')}</div>${activePause?`<div class="pause-info">${esc(activePause.reason)}<span id="pause-limit"></span></div>`:''}`:button('Указать время задержания','timer-start','primary','play')}<div class="timer-rule">Паузы фиксируются с основанием. По достижении лимита ограниченной паузы отсчёт продолжается автоматически.</div></section>`;}
let detentionQuery='',detentionTopic='grounds';
const detentionTopics=[
  ['grounds','Основания',[15,16]],['order','Порядок',[17]],
  ['rights','Права и обязанности',[22,23]],['lawyer','Адвокат',[17,17.4]],
  ['search','Обыск',[29,30]],['release','Освобождение и сроки',[20,21]],
  ['subjects','Кто вправе задерживать',[18,19]],['admin','Административное задержание',[24,25,26,27,28]]
];
function detentionArticles(topic){const entry=detentionTopics.find(t=>t[0]===topic);return articles.filter(a=>a.code==='ПК'&&entry[2].includes(Number(a.ref.split(' ')[0]))&&!L.retired(a)&&(topic!=='lawyer'||Number(a.ref.split(' ')[0])===17.4||/^17 ч\.4/.test(a.ref)));}
function casePage(){const all=articles.filter(a=>a.code==='ПК'&&Number(a.ref.split(' ')[0])>=15&&Number(a.ref.split(' ')[0])<=30&&!L.retired(a));const result=detentionQuery.trim()?L.search(all,detentionQuery):detentionArticles(detentionTopic);
  return `<section class="panel detention-search-panel"><div class="searchbox large">${icon('search')}<input id="detention-search" aria-label="Поиск по законке задержания" value="${esc(detentionQuery)}" placeholder="Найти норму: основания, адвокат, обыск…"></div><div class="detention-topics">${detentionTopics.map(([id,title])=>`<button class="filter-btn ${!detentionQuery&&detentionTopic===id?'selected':''}" data-detention-topic="${id}">${title}</button>`).join('')}</div></section><div class="detention-result-heading"><h2>${detentionQuery?'Результаты поиска':detentionTopics.find(t=>t[0]===detentionTopic)[1]}</h2><span class="muted">${result.length} норм · ПК Boston</span></div><div class="detention-laws">${result.map(a=>`<article class="panel detention-law"><div class="law-card-top"><span class="law-code">${a.code}</span><span class="article-number">${esc(a.ref)}</span><button class="icon-btn favorite ${state.favorites.includes(a.id)?'on':''}" aria-label="В избранное ${esc(a.ref)}" data-action="favorite" data-id="${a.id}">${icon('star')}</button></div><h3>${esc(a.title)}</h3><div class="law-full">${esc(a.text)}</div>${a.sanction?`<div class="notice gold">${esc(a.sanction)}</div>`:''}<div class="button-row"><button class="btn secondary small" data-action="copy-law" data-id="${a.id}">${icon('copy')} Копировать норму</button><a class="btn ghost small" href="${a.source}" target="_blank" rel="noopener">Источник ${icon('link')}</a></div></article>`).join('')||'<div class="empty"><h2>Норма не найдена</h2><p>Попробуй номер статьи или другое слово.</p></div>'}</div>`;
}
function legacyCasePage(){const c=current();if(!c)return emptyCase();const calc=L.calculate(c.charges,articles,c);
  return `<div class="case-tabs"><span class="badge green">В работе</span><span class="case-number">${esc(c.id)}</span><select id="case-select" aria-label="Выбор дела">${state.cases.filter(x=>x.status==='active').map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${esc(x.name||x.id)}</option>`).join('')}</select><span class="muted">Создано ${date(c.createdAt)}</span>${button('Завершить дело','close-case','ghost','archive')}</div><div class="case-layout"><div class="case-main"><section class="panel"><div class="panel-head"><h2>${icon('person')} Участники и обстоятельства</h2><span class="muted">АВТОСОХРАНЕНИЕ</span></div><div class="form-grid">${field('Имя задержанного','name',c.name,'Имя Фамилия')}${field('Номер паспорта','passport',c.passport,'Например, 123456')}${field('Место задержания','location',c.location,'Улица, ориентир',true)}<label class="field"><span>Статус задержанного</span><select data-field="subject" id="field-subject"><option value="civilian" ${c.subject==='civilian'?'selected':''}>Гражданский</option><option value="government" ${c.subject==='government'?'selected':''}>Госслужащий / WN / частный адвокат</option></select></label><label class="field"><span>Основание процедуры</span><select data-field="mode" id="field-mode"><option value="investigation" ${c.mode==='investigation'?'selected':''}>При ведении следствия</option><option value="warrant" ${c.mode==='warrant'?'selected':''}>По ордеру</option></select></label>${c.mode==='warrant'?field('Номер и название ордера','warrant',c.warrant,'Реквизиты документа',true):''}${textarea('Основания задержания','basis',c.basis,'Что послужило основанием? Укажи обстоятельства и пункт ПК 16.',3)}${textarea('Обстоятельства происшествия','facts',c.facts,'Что произошло, где и когда? Отделяй наблюдаемые факты от предположений.',4)}</div>${lawButton('ПК','16 ч.2')}</section><section class="panel"><div class="panel-head"><h2>${icon('book')} Выбранные статьи <span class="count">${c.charges.length}</span></h2><button class="text-link" data-nav="laws">Добавить ${icon('plus')}</button></div>${c.charges.length?c.charges.map(ch=>{const a=articles.find(a=>a.id===ch.id);if(!a)return '';return `<div class="charge"><div class="charge-heading"><button class="text-link" data-action="law" data-id="${a.id}">${a.code} ${esc(a.ref)}</button><button class="icon-btn" data-action="remove-law" data-id="${a.id}" aria-label="Убрать статью ${esc(a.ref)}">${icon('close')}</button></div><h3>${esc(a.title)}</h3><p>${esc(a.sanction||'Нет отдельной санкции')}</p>${a.code==='УК'?`<div class="charge-selects"><label>Стадия<select data-charge="${a.id}" data-prop="stage"><option value="complete" ${ch.stage==='complete'?'selected':''}>Оконченное</option><option value="attempt" ${ch.stage==='attempt'?'selected':''}>Покушение</option><option value="preparation" ${ch.stage==='preparation'?'selected':''}>Приготовление</option></select></label><label>Юрисдикция по источнику<select data-charge="${a.id}" data-prop="jurisdiction">${[['unknown','Не проверена'],['R','R · региональная'],['F/R','F/R · совместная'],['F','F · федеральная'],['M','M · военная'],['E','E · финансовая']].map(([v,t])=>`<option value="${v}" ${ch.jurisdiction===v?'selected':''}>${t}</option>`).join('')}</select></label></div>`:''}</div>`}).join(''):'<div class="empty small"><p>Найди подходящие нормы в законодательке<br>и добавь их в дело.</p></div>'}</section><section class="panel"><div class="panel-head"><h2>${icon('link')} Доказательства <span class="count">${c.evidence.length}</span></h2>${button('Добавить','evidence-new','ghost','plus')}</div>${c.evidence.map(e=>`<div class="evidence"><div class="evidence-icon">${icon('file')}</div><div><strong>${esc(e.title)}</strong><span>${esc(e.timecode||'Таймкод не указан')}</span><p>${esc(e.note)}</p>${safeLink(e.url)?`<a href="${esc(e.url)}" target="_blank" rel="noopener">Открыть материал ${icon('link')}</a>`:''}</div><button class="icon-btn" data-action="evidence-edit" data-id="${e.id}" aria-label="Редактировать доказательство">${icon('settings')}</button></div>`).join('')||'<div class="empty small"><p>Добавь запись, таймкоды и описание того,<br>что подтверждает каждый материал.</p></div>'}</section></div><aside class="case-side">${timerPanel(c)}${calculationPanel(c,calc)}${reminderPanel(c)}<section class="panel"><div class="panel-head"><h2>${icon('clock')} Хронология</h2>${button('Запись','event-new','ghost','plus')}</div>${timeline(c,8)}</section></aside></div>`;
}
function safeLink(url){try{return ['https:','http:'].includes(new URL(url).protocol)}catch{return false}}
function calculationPanel(c,calc){return `<section class="panel"><div class="panel-head"><h2>${icon('scale')} Пределы санкций</h2></div><div class="penalty-number">${calc.strictest||'—'}<span>месяцев · верхний предел УК</span></div><p class="muted">Наиболее строгая из выбранных санкций. Это предел, а не автоматически назначенное наказание.</p>${lawButton('УК','5.2 ч.4')}${calc.rows.some(r=>r.stage!=='complete')?`<div class="notice">Приготовление: ½; покушение: ¾ максимума. ${lawButton('УК','5.2.1 ч.2')}${lawButton('УК','5.2.1 ч.3')}</div>`:''}<label class="check-label"><input type="checkbox" data-field="insultDuringProcedure" ${c.insultDuringProcedure?'checked':''}> УК 17.3 совершена во время процессуальных действий</label>${calc.exceptionalCeiling!=null?`<div class="notice">Возможное полное сложение по исключению: до ${calc.exceptionalCeiling} месяцев. Применимость и меру нужно обосновать.</div>`:''}${calc.administrativeMax?`<div class="fine-line">АК: диапазон суммы штрафов <b>${money(calc.administrativeMin)}–${money(calc.administrativeMax)}</b></div>${lawButton('АК','1.11')}`:''}${calc.unknownJurisdiction.length?`<div class="notice">Юрисдикция ${calc.unknownJurisdiction.length} статей УК не проверена. В базе нет надёжной отметки для каждой статьи: сверь форум и укажи её в карточке.</div>`:''}${calc.outsideJurisdiction.length?`<div class="notice danger">${calc.outsideJurisdiction.map(r=>esc(r.ref)).join(', ')}: отмечена юрисдикция вне обычных полномочий LSCSD. Проверь порядок взаимодействия. ${lawButton('УК','2.8 ч.2')}${lawButton('УК','2.8 ч.3')}</div>`:''}<button class="text-link" data-nav="report">Записать итоговое решение ${icon('arrow')}</button></section>`;}
const pauseReasons=[['lawyer-answer','Ответ адвоката',3,'ПК','17 ч.4.1'],['lawyer-arrival','Прибытие государственного адвоката после принятия вызова',10,'ПК','17 ч.4'],['private-arrival','Прибытие частного адвоката после окончания звонка',10,'ПК','17 ч.4.1'],['lawyer-work','Разбирательство с адвокатом',0,'ПК','20 ч.2'],['prosecutor-answer','Ответ прокурора по требованию адвоката',5,'ПК','17 ч.6'],['prosecutor-arrival','Прибытие прокурора по требованию адвоката',15,'ПК','17 ч.6'],['government-answer','Ответ ОГП при задержании госслужащего',15,'ПК','19 ч.1'],['government-arrival','Прибытие ОГП после ответа при задержании госслужащего',0,'ПК','19 ч.1'],['interrogation','Допрос / экспертиза',0,'ПК','20 ч.2'],['ems','Вызов и освидетельствование EMS',0,'ПК','20 ч.2'],['property','Обыск имущества',0,'ПК','20 ч.2'],['video','Просмотр записи задержанного при автоматическом BOLO',10,'ПК','20 ч.2']];
const reminders=[['lawyer-answer','Ответ адвоката',3,'ПК','17 ч.4.1'],['lawyer-arrival','Прибытие гос. адвоката',10,'ПК','17 ч.4'],['private-arrival','Прибытие частного адвоката',10,'ПК','17 ч.4.1'],['private-talk','Конфиденциальная беседа',10,'ПК','22 ч.1'],['phone','Телефонный звонок',3,'ПК','22 ч.1'],['prosecutor-answer','Ответ прокурора',5,'ПК','17 ч.6'],['prosecutor-arrival','Прибытие прокурора',15,'ПК','17 ч.6'],['government-answer','Ответ ОГП · госслужащий',15,'ПК','19 ч.1'],['sang','Прибытие для изъятия военного билета',12,'ПК','17']];
function reminderPanel(c){return `<section class="panel"><div class="panel-head"><h2>${icon('radio')} Вызовы и напоминания</h2></div><select id="reminder-kind" aria-label="Тип напоминания">${reminders.map(([id,t,m])=>`<option value="${id}">${t} · ${m} мин</option>`).join('')}</select><button class="btn secondary full-width" data-action="reminder-start">${icon('play')} Начать ожидание</button><div class="reminders">${c.reminders.filter(r=>!r.dismissed).map(r=>`<div class="reminder"><div><strong>${esc(r.title)}</strong><span data-reminder="${r.id}"></span></div><button class="icon-btn" data-action="reminder-stop" data-id="${r.id}" aria-label="Завершить ожидание">${icon('check')}</button></div>`).join('')}</div><p class="muted tiny">Напоминание само по себе не приостанавливает процессуальное время.</p></section>`;}
function timeline(c,count=Infinity){return `<div class="timeline">${c.timeline.slice(-count).reverse().map(e=>`<div><time>${stamp(e.at)}</time><p>${esc(e.text)}</p></div>`).join('')||'<p class="muted">Действия появятся здесь.</p>'}</div>`;}
function steps(c){const warrant=c?.mode==='warrant';return [
  ['record','Включить видеофиксацию','Запись задержания и ключевых обстоятельств.','ПК','23 ч.1'],
  ['basis','Проверить основания задержания','Зафиксируй, на каком основании ограничена свобода.','ПК','16 ч.2'],
  ['cuffs','Надеть наручники','Отметь фактическое время ограничения свободы.','ПК',warrant?'17 ч.2':'17 ч.1'],
  ['identify','Предъявить служебную идентификацию','Удостоверение, жетон или иной предусмотренный знак.','ПК',warrant?'17 ч.2':'17 ч.1'],
  ['search','Решить вопрос о первичном обыске','По усмотрению сотрудника; проверь применимое основание.','ПК',warrant?'17 ч.2':'17 ч.1'],
  ['miranda','Разъяснить основания и права','Миранда и проверка понимания; при необходимости повторное разъяснение.','ПК','17 ч.3'],
  ...(warrant?[['warrant','Разъяснить реквизиты ордера','Номер и название документа, являющегося основанием.','ПК','17 ч.2']]:[]),
  ['identity','Установить личность и статус','Проверка принадлежности к госорганам; при следствии — также BOLO.','ПК',warrant?'17 ч.2':'17 ч.1'],
  ['transport','Доставить к месту процессуальных действий','Порядок доставки проверь по выбранной процедуре.','ПК',warrant?'17 ч.2':'17 ч.1'],
  ['rights','Реализовать запрошенные права','Адвокат, звонок, конфиденциальная беседа — по применимым нормам.','ПК','22 ч.1'],
  ...(c?.subject==='government'?[['government','Вызвать руководство и ОГП','Особый порядок, сроки ожидания и основания освобождения.','ПК','19 ч.1']]:[]),
  ['investigate','Провести необходимые следственные действия','Проверить доказательства, доводы и материалы задержанного.','ПК','23 ч.1'],
  ['ticket','Проверить необходимость изъятия военного билета','Зависит от статей и наличия билета.','ПК',warrant?'17 ч.2':'17 ч.1'],
  ['decision','Проверить решение и порядок ареста','Основания освобождения, санкции и процедура ареста.','ПК','27 ч.1']
];}
function procedurePage(){const c=current(),items=steps(c),done=items.filter(([id])=>c?.steps[id]).length;
  return `<div class="procedure-grid"><section class="panel"><div class="panel-head"><h2>${icon('check')} ${c?.mode==='warrant'?'Задержание по ордеру':'Задержание при ведении следствия'}</h2><span class="badge">${done} / ${items.length}</span></div><div class="progress"><div style="width:${done/items.length*100}%"></div></div>${!c?'<div class="notice">Можно изучить порядок. Для фиксации шагов создай карточку задержания.</div>':''}<p class="muted">Это памятка, а применимый порядок — в полном тексте ПК 17. Отмечай только выполненные или проверенные действия.</p>${items.map(([id,t,d,co,r],i)=>`<div class="step ${c?.steps[id]?'done':''}"><label><input type="checkbox" data-step="${id}" ${c?.steps[id]?'checked':''} ${!c?'disabled':''}><span class="step-no">${String(i+1).padStart(2,'0')}</span><div><strong>${t}</strong><p>${d}</p>${c?.steps[id]?`<small>Отмечено ${stamp(c.steps[id])}</small>`:''}</div></label>${lawButton(co,r)}</div>`).join('')}</section><aside><section class="panel miranda"><div class="panel-head"><h2>${icon('shield')} Правило Миранды</h2>${button('Копировать','copy-miranda','ghost','copy')}</div><blockquote>${esc(mirandaText())}</blockquote><p>Удостоверься в понимании. При отсутствии чёткого подтверждения разъясни права вторично и сообщи, что дальнейшего разъяснения не будет.</p>${lawButton('ПК','17 ч.3')}</section><section class="panel"><div class="panel-head"><h2>Быстрые RP-фразы</h2></div>${[['badge','Предъявление жетона','/me предъявил служебный жетон сотрудника LSCSD'],['cuffs','Наручники','/me достал наручники и закрепил их на запястьях задержанного'],['record','Видео записи','/me проверил работу нагрудной камеры'],['documents','Проверка документов','/me сверил данные предъявленного документа с базой данных']].map(([id,t,phrase])=>`<button class="phrase" data-copy="${esc(phrase)}"><span>${t}</span>${icon('copy')}</button>`).join('')}<p class="muted tiny">Копирование текста. Действия в игре выполняешь сам.</p></section>${c?timerPanel(c):''}</aside></div>`;
}
function mirandaText(){const text=law('ПК','17 ч.3')?.text||'';return text.match(/Правило Миранды:\s*"([\s\S]*?)"/)?.[1]||text.split('Примечание:')[0];}
const topics={
  basis:{title:'«Нет оснований для задержания»',description:'Раздели основание задержания и доказательства состава. Сопоставь фактические обстоятельства с ПК 16 ч.2.',refs:[['ПК','16 ч.2'],['УК','1.8 ч.1'],['ПК','20 ч.1']],check:'basis',reply:'Основание задержания: {basis}. Обстоятельства: {facts}. Уточните, какой пункт основания вы оспариваете и почему он неприменим к этим обстоятельствам.'},
  evidence:{title:'«Не представлены доказательства»',description:'По каждому эпизоду укажи материал и таймкод. Проверь достаточность и допустимость, в том числе материалы задержанного.',refs:[['ПК','11 ч.1'],['ПК','12 ч.1'],['ПК','23 ч.1'],['ПК','20 ч.1']],check:'record',reply:'Инкриминируемые нормы: {charges}. Материалы: {evidence}. Прошу уточнить, какой факт не подтверждён либо какое доказательство вы считаете недопустимым и по какому основанию.'},
  miranda:{title:'«Нарушено разъяснение прав»',description:'Проверь запись оглашения, порядок обязательных элементов и проверку понимания. Не заявляй о соблюдении, если запись этого не подтверждает.',refs:[['ПК','17 ч.3'],['ПК','22 ч.1']],check:'miranda',reply:'Предлагаю сверить запись разъяснения прав и подтверждения их понимания. Уточните, какой обязательный элемент или этап был нарушен. Время и содержание действий отражены в хронологии дела.'},
  lawyer:{title:'«Не обеспечено право на адвоката»',description:'Проверь способ вызова, ответ и прибытие, доступ к доверителю и конфиденциальную беседу. Не смешивай время ответа с временем прибытия.',refs:[['ПК','17 ч.4'],['ПК','17 ч.4.1'],['ПК','17.4 ч.2'],['ПК','22 ч.1']],check:'rights',reply:'Предлагаю сверить способ и время вызова адвоката, ответ на вызов, прибытие и предоставление беседы по записи и хронологии. Уточните конкретное действие, ограничившее право на защиту.'},
  time:{title:'«Истёк процессуальный час»',description:'Покажи момент фактического задержания и интервалы приостановки с основаниями. Проверь, относится ли выбранная пауза к этому случаю.',refs:[['ПК','20 ч.1'],['ПК','20 ч.2'],['ПК','19 ч.1']],check:'cuffs',reply:'Начало фактического задержания: {start}. Учтённое процессуальное время: {elapsed}. Приостановки: {pauses}. Предлагаю сверить основания и длительность каждого интервала.'},
  jurisdiction:{title:'«LSCSD не уполномочен по статье»',description:'Сверь юрисдикцию каждой нормы с форумом. Для статей вне полномочий проверь предусмотренный порядок взаимодействия.',refs:[['УК','2.8 ч.2'],['УК','2.8 ч.3'],['АК','5.3']],check:'basis',reply:'Инкриминируемые нормы: {charges}. Юрисдикция и полномочия подлежат проверке по каждой статье. Уточните, какую норму и полномочие вы оспариваете; проверим отметку в источнике и порядок согласования.'},
  prosecutor:{title:'«Требую вызвать прокурора»',description:'При основаниях полагать, что нарушены нормативные акты, ПК 17 ч.6 предусматривает вызов по первому требованию адвоката: 5 минут на ответ, после ответа — до 15 минут на прибытие.',refs:[['ПК','17 ч.6'],['ПК','19 ч.1']],check:'rights',reply:'Уточните предполагаемое нарушение и применимую норму. Требование и указанные основания фиксирую в деле; порядок вызова проверяем по ПК 17 ч.6. При статусе госслужащего дополнительно применим ПК 19.'},
  search:{title:'«Незаконный обыск»',description:'Различай досмотр, личный обыск и обыск транспорта. Проверь основание, вид действия и фактическую последовательность.',refs:[['ПК','29 ч.1'],['ПК','30 ч.1'],['ПК','17 ч.1']],check:'search',reply:'Уточните, какое действие вы оспариваете: досмотр, личный обыск или обыск транспорта. Предлагаю сверить основание, обстоятельства и последовательность действий с записью и соответствующей нормой.'}
};
function defense(c,topic=counselTopic){const t=topics[topic],charged=c.charges.map(ch=>{const a=articles.find(a=>a.id===ch.id);return a?`${a.code} ${a.ref} — ${a.title}`:'[статья отсутствует в базе]'}).join('; ');
  const vars={basis:c.basis||'[укажи основание]',facts:c.facts||'[запиши обстоятельства]',charges:charged||'[статьи не выбраны]',evidence:c.evidence.map(e=>`${e.title} (${e.timecode||'таймкод не указан'}): ${e.note||'содержание не описано'}`).join('; ')||'[доказательства не добавлены]',start:c.timer.startedAt?new Date(c.timer.startedAt).toLocaleString('ru-RU'):'[время не указано]',elapsed:L.formatTime(L.elapsed(c.timer)),pauses:c.timer.pauses.map(p=>`${p.reason}: ${stamp(p.start)}–${p.end?stamp(p.end):'текущая'}${p.capMs?' (лимит '+p.capMs/60000+' мин)':''}`).join('; ')||'не зафиксированы'};
  return t.reply.replace(/\{(\w+)\}/g,(_,k)=>(vars[k]||'').replace(/[.\s]+$/,'')).replace(/\.\./g,'.');
}
function counselPage(){const c=current(),t=topics[counselTopic];
  return `<div class="notice gold">Аргументы опираются на записи дела. Отсутствие отметки означает «не зафиксировано», а не автоматически доказанное нарушение.</div><div class="counsel-layout"><section class="panel counsel-menu"><div class="panel-head"><h2>Возражение адвоката</h2></div><div class="searchbox">${icon('search')}<input id="objection" value="${esc(objection)}" placeholder="Найти тему: права, обыск…" aria-label="Поиск возражения"></div>${Object.entries(topics).filter(([id,t])=>!objection||L.normalize(t.title+' '+t.description).includes(L.normalize(objection))).map(([id,t])=>`<button class="topic ${id===counselTopic?'selected':''}" data-topic="${id}">${icon('scale')}<span>${t.title}</span>${icon('arrow')}</button>`).join('')||'<p class="muted">Нет темы. Проверь норму через законодательку.</p>'}</section><div><section class="panel"><div class="panel-head"><span class="eyebrow">РАЗБОР ВОЗРАЖЕНИЯ</span>${icon('scale')}</div><h2 class="topic-title">${t.title}</h2><p class="topic-description">${t.description}</p><div class="section-label">ОПОРНЫЕ НОРМЫ</div><div class="ref-chips">${t.refs.map(([co,r])=>lawButton(co,r)).join('')}</div><div class="section-label">ПРОВЕРКА ТЕКУЩЕГО ДЕЛА</div>${c?`<div class="audit">${audit(c).map(([ok,text])=>`<div class="${ok?'ok':'missing'}">${icon(ok?'check':'alert')}<span>${text}</span></div>`).join('')}</div><div class="response"><div class="panel-head"><h3>Черновик ответа</h3>${button('Копировать','copy-defense','ghost','copy')}</div><p>${esc(defense(c))}</p></div>`:'<div class="notice">Создай дело и добавь обстоятельства, статьи и доказательства. Тогда здесь появится черновик ответа.</div>'}</section>${c?`<section class="panel"><div class="panel-head"><h2>Заметки по разбирательству</h2></div>${textarea('Возражения, ходатайства и твои действия','counselNotes',c.counselNotes,'Записывай, что именно оспаривают, на какую норму ссылаются и что установлено.',5)}${button('Добавить событие в хронологию','event-new','secondary','plus')}</section>`:''}<section class="panel"><div class="panel-head"><h2>Как строить обоснование</h2></div><div class="defense-flow">${['Наблюдаемый факт','Признаки состава','Доказательства','Соблюдение процедуры'].map((s,i)=>`<div><b>0${i+1}</b><span>${s}</span></div>`).join('')}</div><p class="muted">Если возражение подтверждает ошибку, исправь её и проверь основания освобождения по ПК 20.</p>${lawButton('ПК','20 ч.1')}</section></div></div>`;
}
function audit(c){const unknown=c.charges.some(ch=>ch.jurisdiction==='unknown'&&articles.find(a=>a.id===ch.id)?.code==='УК');return [[!!c.basis,'Основания задержания '+(c.basis?'записаны':'не записаны')],[!!c.charges.length,'Статьи '+(c.charges.length?'выбраны':'не выбраны')],[!!c.evidence.length,'Доказательства '+(c.evidence.length?'добавлены':'не добавлены')],[!!c.steps.miranda,'Разъяснение прав '+(c.steps.miranda?'отмечено':'не отмечено')],[!!c.steps.rights,'Реализация прав '+(c.steps.rights?'отмечена':'не отмечена')],[!!c.timer.startedAt,'Время задержания '+(c.timer.startedAt?'указано':'не указано')],[!unknown,'Юрисдикция '+(unknown?'требует проверки':'выбранных статей отмечена или УК не выбраны')]];}
function reportText(c,type='report'){const p=state.profile;return `${type==='brief'?'КРАТКОЕ ОБОСНОВАНИЕ ЗАДЕРЖАНИЯ':'РАПОРТ · ЧЕРНОВИК'}\nLSCSD · Boston\nДело ${c.id} · ${date(c.createdAt)}\n\nСотрудник: ${p.name||'[имя]'} | ${p.rank||'[должность]'} | Жетон: ${p.badge||'[номер]'} | Позывной: ${p.callsign||'[позывной]'}\nЗадержанный: ${c.name||'[имя]'} | Паспорт: ${c.passport||'[номер]'}\nМесто: ${c.location||'[место]'}\nФактическое задержание: ${c.timer.startedAt?new Date(c.timer.startedAt).toLocaleString('ru-RU'):'[время не указано]'}\nПроцедура: ${c.mode==='warrant'?'По ордеру: '+(c.warrant||'[реквизиты]'):'При ведении следствия'}\n\nОСНОВАНИЯ\n${c.basis||'[укажи основания и пункт ПК]'}\n\nОБСТОЯТЕЛЬСТВА\n${c.facts||'[запиши факты]'}\n\nВЫБРАННЫЕ НОРМЫ\n${c.charges.map(ch=>{const a=articles.find(a=>a.id===ch.id);return a?`${a.code} ${a.ref} — ${a.title}\nСанкция: ${a.sanction||'без отдельной санкции'}${a.code==='УК'?`\nЮрисдикция: ${ch.jurisdiction==='unknown'?'не проверена':ch.jurisdiction}\nСтадия: ${{complete:'оконченное',attempt:'покушение',preparation:'приготовление'}[ch.stage]||'не указана'}`:''}\nИсточник: ${a.source}`:''}).join('\n\n')||'[статьи не выбраны]'}\n\nДОКАЗАТЕЛЬСТВА\n${c.evidence.map((e,i)=>`${i+1}. ${e.title}\nТаймкод: ${e.timecode||'[не указан]'}\nСодержание: ${e.note||'[не описано]'}\nСсылка: ${e.url||'[не указана]'}`).join('\n\n')||'[материалы не добавлены]'}\n\nХРОНОЛОГИЯ\n${c.timeline.map(e=>`${new Date(e.at).toLocaleString('ru-RU')} — ${e.text}`).join('\n')||'[события не записаны]'}\n\nРАЗБИРАТЕЛЬСТВО С АДВОКАТОМ\n${c.counselNotes||'[заметки отсутствуют]'}\n\nИТОГОВОЕ РЕШЕНИЕ\n${c.decision||'[решение не записано]'}\n\nБаза законодательки: ${DB.source}\nДата снимка базы: ${date(DB.importedAt)}\nЧерновик подготовлен из внесённых сотрудником данных. Проверить перед использованием.`;}
function reportPage(){const c=current();if(!c)return emptyCase();return `<div class="report-layout"><section class="panel"><div class="panel-head"><h2>${icon('file')} Черновик рапорта</h2><span class="badge gold">На проверку</span></div><div class="report-toolbar">${button('Копировать','copy-report','primary','copy')}${button('Скачать .txt','download-report','secondary','download')}${button('Краткое обоснование','copy-brief','ghost','file')}</div><pre class="report-preview">${esc(reportText(c))}</pre></section><aside><section class="panel"><div class="panel-head"><h2>Итоговое решение</h2></div>${textarea('Мера, обоснование, реквизиты','decision',c.decision,'Запиши фактически принятое решение, меру наказания и обоснование. Для освобождения — основание.',7)}<p class="muted">Назначение наказания остаётся твоим решением в пределах полномочий и применимых норм.</p>${lawButton('УК','5.2 ч.4')}</section><section class="panel"><div class="panel-head"><h2>Перед отправкой</h2></div><div class="audit">${audit(c).map(([ok,t])=>`<div class="${ok?'ok':'missing'}">${icon(ok?'check':'alert')}<span>${t}</span></div>`).join('')}</div></section>${button('Завершить и сохранить в архив','close-case','secondary','archive')}</aside></div>`;}
function archivePage(){return `<div class="archive-stats"><span>${state.cases.length} дел всего</span><span>${state.cases.filter(c=>c.status==='closed').length} завершено</span>${button('Резервная копия','backup','secondary','download')}</div><div class="archive-list">${state.cases.slice().reverse().map(c=>`<article class="panel archive-card"><div class="archive-icon">${icon('case')}</div><div><div class="case-number">${esc(c.id)} · ${date(c.createdAt)}</div><h2>${esc(c.name||'Личность не заполнена')}</h2><p>${esc(c.location||'Место не указано')} · ${c.charges.length} статей · ${c.evidence.length} доказательств</p></div><span class="badge ${c.status==='closed'?'':'green'}">${c.status==='closed'?'Завершено':'В работе'}</span><button class="btn secondary" data-action="open-case" data-id="${c.id}">Материалы ${icon('arrow')}</button></article>`).join('')||'<div class="empty big">'+icon('archive')+'<h2>Здесь будет история твоих дел</h2><p>Карточки сохраняются автоматически.<br>Завершённое дело можно открыть и продолжить.</p></div>'}</div>`;}
function settingsPage(){return `<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>${icon('person')} Профиль сотрудника</h2></div><div class="form-grid">${field('Имя персонажа','profile.name',state.profile.name,'Имя Фамилия')}${field('Должность','profile.rank',state.profile.rank,'Deputy Sheriff')}${field('Номер жетона','profile.badge',state.profile.badge,'Номер')}${field('Позывной','profile.callsign',state.profile.callsign,'Например, 2-Adam-12')}</div><p class="muted">Профиль используется в черновиках рапортов.</p></section><section class="panel"><div class="panel-head"><h2>${icon('settings')} На смене</h2></div><label class="setting"><div><strong>Звуковые напоминания</strong><span>Сигнал по завершении ожидания</span></div><input type="checkbox" data-setting="sound" ${state.settings.sound?'checked':''}></label><label class="setting"><div><strong>Компактный режим</strong><span>Узкое окно рядом с игрой</span></div><input type="checkbox" data-setting="compact" ${state.settings.compact?'checked':''}></label><label class="setting"><div><strong>Поверх других окон</strong><span>${window.desktop?'Доступно в приложении Windows':'Доступно в приложении Windows; здесь режим браузера'}</span></div><input type="checkbox" data-setting="top" ${state.settings.top?'checked':''} ${!window.desktop?'disabled':''}></label><p class="muted tiny">В полноэкранной игре поверх окон может не отображаться. Используй оконный режим без рамки.</p></section><section class="panel"><div class="panel-head"><h2>${icon('archive')} Данные и резервные копии</h2></div><p class="muted">Дела хранятся на этом устройстве. Экспорт сохраняет профиль, все дела, избранное и хронологию. Импорт добавляет отсутствующие дела, сохраняя существующие.</p><div class="button-row">${button('Экспорт .json','backup','primary','download')}${button('Импорт .json','restore','secondary','archive')}</div>${storageBroken?button('Скачать исходные данные','raw-backup','secondary','download'):''}<p class="tiny muted">Резервные копии не отправляются на внешние сервисы.</p></section><section class="panel"><div class="panel-head"><h2>${icon('book')} Источники законодательки</h2><span class="badge green">Офлайн</span></div><div class="database-stats">${['УК','АК','ДК','ПК'].map(co=>`<div><b>${articles.filter(a=>a.code===co).length}</b><span>${co}</span></div>`).join('')}</div><p class="muted">Снимок Boston от ${date(DB.importedAt)}. Обновления сайта не появляются автоматически; перед спорным решением сверяй исходный документ.</p><a class="text-link" href="${DB.source}" target="_blank" rel="noopener">Открыть базу Boston ${icon('link')}</a><div class="source-links">${['УК','АК','ДК','ПК'].map(co=>`<a href="${articles.find(a=>a.code===co).source}" target="_blank" rel="noopener">${co} · форум ${icon('link')}</a>`).join('')}</div><p class="tiny muted">Тексты: Majestic Rules и форум Majestic RP. Приложение — личный помощник, без связи с игровым клиентом.</p></section></div>`;}
function showModal(html){const m=$('#modal');m.innerHTML=`<div class="modal-body">${html}<button class="modal-close icon-btn" data-action="modal-close" aria-label="Закрыть">${icon('close')}</button></div>`;if(!m.open)m.showModal();}
function closeModal(){$('#modal').close();}
function showLaw(id){const a=articles.find(a=>a.id===id);if(!a)return;showModal(`<div class="eyebrow">BOSTON / ${a.code} ${esc(a.ref)}</div><h2>${esc(a.title)}</h2><div class="law-full">${esc(a.text)}</div>${a.sanction?`<div class="notice gold"><strong>Санкция</strong><p>${esc(a.sanction)}</p></div>`:''}<div class="button-row"><button class="btn primary" data-action="add-law" data-id="${a.id}" ${L.retired(a)?'disabled':''}>${icon('plus')} Добавить в дело</button><button class="btn secondary" data-action="copy-law" data-id="${a.id}">${icon('copy')} Копировать</button><a class="btn ghost" href="${a.source}" target="_blank" rel="noopener">Источник ${icon('link')}</a></div>`);}
function newCase(){const c=L.makeCase('BOS-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+crypto.randomUUID().slice(0,6).toUpperCase());state.cases.push(c);state.activeId=c.id;log('Создана карточка задержания. Фактическое время ещё не указано.',c);view='materials';render();toast('Карточка создана. Укажи фактическое время задержания.');}
function addLaw(id){const a=articles.find(a=>a.id===id);if(!a||L.retired(a))return;let c=current();if(!c||c.status==='closed'){newCase();c=current();}if(c.charges.some(ch=>ch.id===id)){toast('Статья уже в деле');return;}c.charges.push({id,code:a.code,ref:a.ref,stage:'complete',jurisdiction:'unknown'});log('Добавлена норма: '+a.code+' '+a.ref);render();toast(a.code+' '+a.ref+' добавлена в дело');}
function dateInput(t){const d=new Date(t);return new Date(t-d.getTimezoneOffset()*60000).toISOString().slice(0,19);}
function timerModal(){const c=current();if(!c)return;showModal(`<h2>Фактическое задержание</h2><p class="muted">Укажи момент ограничения свободы передвижения, а не время создания карточки.</p><label class="field"><span>Дата и время · локальное время компьютера</span><input type="datetime-local" step="1" id="actual-time" value="${dateInput(c.timer.startedAt||Date.now())}"></label><p class="muted tiny">Ранее записанные паузы сохраняются. Проверь их, если меняешь начало.</p>${button('Сохранить время','timer-confirm','primary','clock')}`);}
function pauseModal(){const c=current();if(!c?.timer.startedAt)return toast('Сначала укажи время задержания');if(c.timer.stoppedAt)return;showModal(`<h2>Приостановка времени</h2><p class="muted">Выбери фактически наступившее основание. Пауза не заменяет вызов и действия в игре.</p><label class="field"><span>Основание</span><select id="pause-reason">${pauseReasons.map(([id,t,m,co,r])=>`<option value="${id}">${t} · ${m?m+' мин':'без заданного лимита'} · ${co} ${r}</option>`).join('')}</select></label>${button('Зафиксировать паузу','pause-confirm','primary','pause')}`);}
function evidenceModal(id){const c=current();if(!c)return;const e=c.evidence.find(e=>e.id===id)||{id:'',title:'',url:'',timecode:'',note:''};showModal(`<h2>${e.id?'Редактировать':'Добавить'} доказательство</h2><div class="form-grid"><label class="field wide"><span>Название</span><input id="e-title" value="${esc(e.title)}" placeholder="Нагрудная камера, эпизод №1"></label><label class="field"><span>Таймкод</span><input id="e-timecode" value="${esc(e.timecode)}" placeholder="02:14–02:38"></label><label class="field"><span>Ссылка на материал</span><input id="e-url" value="${esc(e.url)}" placeholder="https://…"></label><label class="field wide"><span>Что подтверждает</span><textarea id="e-note" rows="4" placeholder="Действие, признаки состава, связь со статьёй">${esc(e.note)}</textarea></label></div><button class="btn primary" data-action="evidence-save" data-id="${e.id}">${icon('check')} Сохранить материал</button>`);}
function eventModal(){if(!current())return;showModal(`<h2>Событие в хронологии</h2><label class="field"><span>Что произошло</span><textarea id="event-text" rows="4" placeholder="Адвокат прибыл; оглашены основания; получено возражение…"></textarea></label>${button('Зафиксировать сейчас','event-save','primary','check')}`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Скопировано');}catch{showModal(`<h2>Текст для копирования</h2><textarea id="copy-fallback" rows="12">${esc(text)}</textarea><p class="muted">Выдели текст и нажми Ctrl+C.</p>`);$('#copy-fallback').select();}}
function download(content,name,type='text/plain'){const blob=new Blob([content],{type:type+';charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function setSetting(key,value){state.settings[key]=value;if(window.desktop){if(key==='top')state.settings.top=await window.desktop.setAlwaysOnTop(value);if(key==='compact')await window.desktop.setCompact(value);}save();render();}
document.addEventListener('click',async ev=>{
  const el=ev.target.closest('button,[data-nav],[data-search],[data-topic],[data-copy]');if(!el)return;
  if(el.dataset.nav){view=el.dataset.nav;render();window.scrollTo(0,0);return;}
  if(el.dataset.search){query=el.dataset.search;code='Все';view='laws';limit=30;render();return;}
  if(el.dataset.topic){counselTopic=el.dataset.topic;render();return;}
  if(el.dataset.detentionTopic){detentionTopic=el.dataset.detentionTopic;detentionQuery='';render();return;}
  if(el.dataset.copy){copy(el.dataset.copy);return;}
  if(el.dataset.codeFilter){code=el.dataset.codeFilter;limit=30;render();return;}
  const action=el.dataset.action,id=el.dataset.id,c=current();
  switch(action){
    case 'new':closeModal();newCase();break;
    case 'go-case':view='case';render();break;
    case 'modal-close':closeModal();break;
    case 'law':showLaw(id);break;
    case 'law-ref':showLaw(law(el.dataset.code,el.dataset.ref)?.id);break;
    case 'copy-law':{const a=articles.find(a=>a.id===id);copy(`${a.code} ${a.ref} — ${a.title}\n${a.text}\n${a.sanction}\nИсточник: ${a.source}`);break;}
    case 'add-law':addLaw(id);break;
    case 'favorite':state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();break;
    case 'favorites-filter':favoritesOnly=!favoritesOnly;limit=30;render();break;
    case 'clear-search':query='';code='Все';favoritesOnly=false;sanctionOnly=false;showRetired=false;limit=30;render();break;
    case 'more':limit+=30;render();break;
    case 'remove-law':if(c){const a=articles.find(a=>a.id===id);c.charges=c.charges.filter(ch=>ch.id!==id);log('Убрана норма: '+a.code+' '+a.ref);render();}break;
    case 'timer-start':case 'timer-edit':timerModal();break;
    case 'timer-confirm':{const t=new Date($('#actual-time').value).getTime();if(!Number.isFinite(t)||t>Date.now()+1000){toast('Укажи корректное время, не в будущем');break;}c.timer.startedAt=t;c.timer.stoppedAt=null;c.timer.overtimeNotified=false;log('Указано фактическое время задержания: '+new Date(t).toLocaleString('ru-RU'));closeModal();render();break;}
    case 'pause':pauseModal();break;
    case 'pause-confirm':{const r=pauseReasons.find(r=>r[0]===$('#pause-reason').value);c.timer.pauses.push({start:Date.now(),end:null,reason:r[1],capMs:r[2]*60000,ref:r[3]+' '+r[4]});log('Приостановка: '+r[1]+'; основание '+r[3]+' '+r[4]);closeModal();render();break;}
    case 'resume':{const p=c.timer.pauses.findLast(p=>!p.end);if(p){p.end=Date.now();log('Завершена пауза: '+p.reason);render();}break;}
    case 'reminder-start':{if(!c)return;const r=reminders.find(r=>r[0]===$('#reminder-kind').value);if(c.reminders.some(x=>x.kind===r[0]&&!x.dismissed)){toast('Такое ожидание уже запущено');break;}c.reminders.push({id:crypto.randomUUID(),kind:r[0],title:r[1],startedAt:Date.now(),deadline:Date.now()+r[2]*60000,notified:false,dismissed:false});log('Начато ожидание: '+r[1]+' · '+r[2]+' мин; '+r[3]+' '+r[4]);render();break;}
    case 'reminder-stop':{const r=c?.reminders.find(r=>r.id===id);if(r){r.dismissed=true;log('Завершено ожидание: '+r.title);render();}break;}
    case 'evidence-new':evidenceModal();break;
    case 'evidence-edit':evidenceModal(id);break;
    case 'evidence-save':{const title=$('#e-title').value.trim(),url=$('#e-url').value.trim();if(!title){toast('Добавь название материала');break;}if(url&&!safeLink(url)){toast('Ссылка должна начинаться с http:// или https://');break;}const e={id:id||crypto.randomUUID(),title,url,timecode:$('#e-timecode').value.trim(),note:$('#e-note').value.trim()};const i=c.evidence.findIndex(x=>x.id===id);if(i>=0)c.evidence[i]=e;else c.evidence.push(e);log((i>=0?'Обновлено':'Добавлено')+' доказательство: '+title);closeModal();render();break;}
    case 'event-new':eventModal();break;
    case 'event-save':{const text=$('#event-text').value.trim();if(!text)return toast('Опиши событие');log(text);closeModal();render();break;}
    case 'copy-miranda':copy(mirandaText());break;
    case 'copy-defense':if(c)copy(defense(c));break;
    case 'copy-report':if(c)copy(reportText(c));break;
    case 'copy-brief':if(c)copy(reportText(c,'brief'));break;
    case 'download-report':if(c)download(reportText(c),c.id+'-rapport.txt');break;
    case 'close-case':if(c)showModal(`<h2>Завершение дела</h2><p class="muted">Материалы сохранятся в архиве. Дело можно будет открыть снова.</p><label class="field"><span>Итоговое решение</span><textarea id="close-decision" rows="5" placeholder="Мера наказания или основание освобождения">${esc(c.decision)}</textarea></label>${button('Сохранить в архив','close-confirm','primary','archive')}`);break;
    case 'close-confirm':{c.decision=$('#close-decision').value.trim();if(!c.decision){toast('Запиши итоговое решение');break;}const now=Date.now();c.timer.stoppedAt=now;c.timer.pauses.forEach(p=>{if(!p.end)p.end=now});c.reminders.forEach(r=>r.dismissed=true);c.status='closed';c.closedAt=now;log('Дело завершено: '+c.decision);state.activeId=state.cases.findLast(x=>x.status==='active')?.id||null;save();closeModal();view='archive';render();break;}
    case 'open-case':{const target=state.cases.find(c=>c.id===id);if(!target)break;if(target.status==='closed'){showModal(`<h2>${esc(target.name||target.id)}</h2><div class="report-toolbar"><button class="btn primary" data-action="archive-download" data-id="${id}">${icon('download')} Скачать рапорт</button><button class="btn secondary" data-action="reopen-case" data-id="${id}">Продолжить дело</button></div><pre class="report-preview">${esc(reportText(target))}</pre>`);}else{state.activeId=id;view='materials';save();render();}break;}
    case 'archive-download':download(reportText(state.cases.find(c=>c.id===id)),id+'-rapport.txt');break;
    case 'reopen-case':{const target=state.cases.find(c=>c.id===id);target.status='active';state.activeId=id;log('Дело открыто снова. Завершённый таймер сохранён; новый отсчёт требует явного уточнения времени.',target);closeModal();view='materials';render();break;}
    case 'backup':download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'Boston-Duty-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('Резервная копия подготовлена');break;
    case 'raw-backup':download(localStorage.getItem('boston-duty-v1')||'','Boston-Duty-recovery.json','application/json');break;
    case 'restore':$('#backup-file').click();break;
    case 'top':if(window.desktop)await setSetting('top',!state.settings.top);else toast('Поверх окон работает в приложении Windows');break;
  }
});
let renderTimeout;
document.addEventListener('input',ev=>{
  const el=ev.target,c=current();
  if(el.id==='law-search'){query=el.value;limit=30;clearTimeout(renderTimeout);renderTimeout=setTimeout(render,120);}
  if(el.id==='detention-search'){detentionQuery=el.value;clearTimeout(renderTimeout);renderTimeout=setTimeout(render,120);}
  if(el.id==='objection'){objection=el.value;clearTimeout(renderTimeout);renderTimeout=setTimeout(render,120);}
  if(el.dataset.field){const k=el.dataset.field,v=el.type==='checkbox'?el.checked:el.value;if(k.startsWith('profile.')){state.profile[k.slice(8)]=v;save();}else if(c){c[k]=v;save();}}
});
document.addEventListener('change',async ev=>{const el=ev.target,c=current();
  if(el.id==='sanction-filter'){sanctionOnly=el.checked;limit=30;render();}
  if(el.id==='retired-filter'){showRetired=el.checked;render();}
  if(el.id==='case-select'){state.activeId=el.value;save();render();}
  if(el.dataset.setting)await setSetting(el.dataset.setting,el.checked);
  if(el.dataset.field&&c){if(['mode','subject','insultDuringProcedure'].includes(el.dataset.field)){log('Обновлено: '+({mode:'тип процедуры',subject:'статус задержанного',insultDuringProcedure:'обстоятельства УК 17.3'}[el.dataset.field]));render();}else if(view==='report')render();}
  if(el.dataset.charge&&c){const ch=c.charges.find(ch=>ch.id===el.dataset.charge);ch[el.dataset.prop]=el.value;log('Уточнение '+ch.code+' '+ch.ref+': '+el.dataset.prop+' = '+el.value);render();}
  if(el.dataset.step&&c){const id=el.dataset.step,t=steps(c).find(s=>s[0]===id)?.[1];if(el.checked)c.steps[id]=Date.now();else delete c.steps[id];log((el.checked?'Отмечено: ':'Снята отметка: ')+t);render();}
  if(el.id==='backup-file'){const file=el.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Файл больше 5 МБ');const data=L.validateBackup(JSON.parse(await file.text()));if(data.helper&&typeof importDesk==='function')importDesk(data.helper);const existing=new Set(state.cases.map(c=>c.id));const added=data.cases.filter(c=>!existing.has(c.id));state.cases.push(...added);state.favorites=[...new Set([...state.favorites,...(data.favorites||[]).filter(id=>articles.some(a=>a.id===id))])];if(!state.profile.name&&data.profile)state.profile={...state.profile,...data.profile};if(!state.activeId)state.activeId=state.cases.find(c=>c.status==='active')?.id||null;save();render();toast(`Добавлено дел: ${added.length}. Существующие сохранены.`);}catch(e){toast('Импорт не выполнен: '+e.message);}el.value='';}
});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();view='laws';render();$('#law-search').focus();}if(ev.key==='Enter'&&ev.target.id==='home-search'){query=ev.target.value;code='Все';view='laws';limit=30;render();}});
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal'))closeModal()});
let audio;
function beep(){if(!state.settings.sound)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=740;g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.5);o.start();o.stop(audio.currentTime+.5);}catch{}}
document.addEventListener('pointerdown',()=>{if(!state.settings.sound||audio)return;try{audio=new (window.AudioContext||window.webkitAudioContext)();audio.resume();}catch{}},{once:true});
function tick(){const now=Date.now(),c=current();let refresh=false;
  for(const x of state.cases.filter(x=>x.status==='active')){
    for(const p of x.timer.pauses.filter(p=>!p.end&&p.capMs&&p.start+p.capMs<=now)){
      p.end=p.start+p.capMs;log('Истёк лимит паузы: '+p.reason+'; отсчёт продолжен автоматически. Проверь последствия по '+p.ref+'.',x);
      toast('Лимит паузы истёк: '+p.reason+' · '+(x.name||x.id));beep();if(x===c)refresh=true;
    }
    const ms=L.elapsed(x.timer,now);
    if(ms>=3600000&&!x.timer.overtimeNotified&&!x.timer.stoppedAt){x.timer.overtimeNotified=true;save();toast((x.name||x.id)+': процессуальное время достигло часа. Проверь ПК 20.');beep();}
    if(ms<3600000&&x.timer.overtimeNotified){x.timer.overtimeNotified=false;save();}
  }
  if(refresh){render();return;}
  if($('#wall-clock'))$('#wall-clock').textContent=stamp(now);
  if(c){const elapsed=L.elapsed(c.timer,now);document.querySelectorAll('[data-process-clock]').forEach(el=>{el.textContent=L.formatTime(elapsed);el.classList.toggle('overtime',elapsed>=3600000);});const p=c.timer.pauses.findLast(p=>!p.end);if($('#pause-limit'))$('#pause-limit').textContent=p?.capMs?'До лимита: '+L.formatTime(p.start+p.capMs-now):'Без заданного лимита — завершить вручную';}
  for(const x of state.cases.filter(x=>x.status==='active'))for(const r of x.reminders.filter(r=>!r.dismissed)){const el=document.querySelector(`[data-reminder="${r.id}"]`);if(el){el.textContent=now>=r.deadline?'Срок ожидания истёк':L.formatTime(r.deadline-now);el.classList.toggle('overtime',now>=r.deadline);}if(now>=r.deadline&&!r.notified){r.notified=true;log('Истёк срок ожидания: '+r.title,x);toast(r.title+': время истекло · '+(x.name||x.id));beep();}}
}
if(window.desktop){window.desktop.setAlwaysOnTop(state.settings.top);window.desktop.setCompact(state.settings.compact);}
render();setInterval(tick,1000);
